#!/usr/bin/env bash

if [[ -n "${HYPRDOTS_THEME_RENDER_LOADED:-}" ]]; then
  return 0
fi

readonly HYPRDOTS_THEME_RENDER_LOADED=1

# shellcheck source=common.sh
source "$(dirname -- "${BASH_SOURCE[0]}")/common.sh"

render_rasi_palette() {
  local output="$1"

  cat >"$output" <<EOF_RASI
/* Generated by Hyprdots theme manager. */
* {
    rosewater: $COLOR_ROSEWATER;
    flamingo:  $COLOR_FLAMINGO;
    pink:      $COLOR_PINK;
    mauve:     $COLOR_MAUVE;
    red:       $COLOR_RED;
    maroon:    $COLOR_MAROON;
    peach:     $COLOR_PEACH;
    yellow:    $COLOR_YELLOW;
    green:     $COLOR_GREEN;
    teal:      $COLOR_TEAL;
    sky:       $COLOR_SKY;
    sapphire:  $COLOR_SAPPHIRE;
    blue:      $COLOR_BLUE;
    lavender:  $COLOR_LAVENDER;

    text:      $COLOR_TEXT;
    subtext1:  $COLOR_SUBTEXT1;
    subtext0:  $COLOR_SUBTEXT0;

    overlay2:  $COLOR_OVERLAY2;
    overlay1:  $COLOR_OVERLAY1;
    overlay0:  $COLOR_OVERLAY0;

    surface2:  $COLOR_SURFACE2;
    surface1:  $COLOR_SURFACE1;
    surface0:  $COLOR_SURFACE0;

    base:      $COLOR_BASE;
    mantle:    $COLOR_MANTLE;
    crust:     $COLOR_CRUST;
}
EOF_RASI
}

render_waybar_palette() {
