render_swaync_palette() {
  local output="$1"
  local base_rgb
  local surface0_rgb

  base_rgb="$(theme_rgb_csv "$COLOR_BASE")"
  surface0_rgb="$(theme_rgb_csv "$COLOR_SURFACE0")"

  cat >"$output" <<EOF_CSS
/* Generated by Hyprdots theme manager. */
:root {
    --rosewater: $COLOR_ROSEWATER;
    --flamingo: $COLOR_FLAMINGO;
    --pink: $COLOR_PINK;
    --mauve: $COLOR_MAUVE;
    --red: $COLOR_RED;
    --maroon: $COLOR_MAROON;
    --peach: $COLOR_PEACH;
    --yellow: $COLOR_YELLOW;
    --green: $COLOR_GREEN;
    --teal: $COLOR_TEAL;
    --sky: $COLOR_SKY;
    --sapphire: $COLOR_SAPPHIRE;
    --blue: $COLOR_BLUE;
    --lavender: $COLOR_LAVENDER;

    --text: $COLOR_TEXT;
    --subtext1: $COLOR_SUBTEXT1;
    --subtext0: $COLOR_SUBTEXT0;

    --overlay2: $COLOR_OVERLAY2;
    --overlay1: $COLOR_OVERLAY1;
    --overlay0: $COLOR_OVERLAY0;

    --surface2: $COLOR_SURFACE2;
    --surface1: $COLOR_SURFACE1;
    --surface0: $COLOR_SURFACE0;

    --base: $COLOR_BASE;
    --mantle: $COLOR_MANTLE;
    --crust: $COLOR_CRUST;

    --cc-bg: rgba($base_rgb, 0.88);
    --noti-bg: $surface0_rgb;
    --noti-bg-alpha: 0.92;
    --floating-noti-bg-alpha: 0.82;
    --noti-bg-darker: var(--mantle);
    --noti-bg-hover: var(--surface1);
    --noti-bg-focus: var(--surface1);
    --noti-border-color: var(--surface1);
    --noti-close-bg: var(--surface1);
    --noti-close-bg-hover: var(--red);
    --text-color: var(--text);
    --text-color-disabled: var(--overlay0);
    --bg-selected: var(--mauve);
    --accent: var(--mauve);
    --accent-text: var(--crust);
    --critical: var(--red);

    --border-radius: 12px;
    --notification-icon-size: 48px;
    --notification-app-icon-size: 20px;
    --notification-group-icon-size: 28px;
    --font-size-body: 14px;
    --font-size-summary: 15px;
}
EOF_CSS
}

