render_hyprlock_palette() {
  local output="$1"
  local crust_rgb
  local surface2_rgb
  local text_rgb

  crust_rgb="$(theme_rgb_csv "$COLOR_CRUST")"
  surface2_rgb="$(theme_rgb_csv "$COLOR_SURFACE2")"
  text_rgb="$(theme_rgb_csv "$COLOR_TEXT")"
  cat >"$output" <<EOF_HYPR
# Generated by Hyprdots theme manager.
\$rosewater = rgb($(theme_hex "$COLOR_ROSEWATER"))
\$flamingo = rgb($(theme_hex "$COLOR_FLAMINGO"))
\$pink = rgb($(theme_hex "$COLOR_PINK"))
\$mauve = rgb($(theme_hex "$COLOR_MAUVE"))
\$red = rgb($(theme_hex "$COLOR_RED"))
\$maroon = rgb($(theme_hex "$COLOR_MAROON"))
\$peach = rgb($(theme_hex "$COLOR_PEACH"))
\$yellow = rgb($(theme_hex "$COLOR_YELLOW"))
\$green = rgb($(theme_hex "$COLOR_GREEN"))
\$teal = rgb($(theme_hex "$COLOR_TEAL"))
\$sky = rgb($(theme_hex "$COLOR_SKY"))
\$sapphire = rgb($(theme_hex "$COLOR_SAPPHIRE"))
\$blue = rgb($(theme_hex "$COLOR_BLUE"))
\$lavender = rgb($(theme_hex "$COLOR_LAVENDER"))

\$text = rgb($(theme_hex "$COLOR_TEXT"))
\$subtext1 = rgb($(theme_hex "$COLOR_SUBTEXT1"))
\$subtext0 = rgb($(theme_hex "$COLOR_SUBTEXT0"))
\$overlay2 = rgb($(theme_hex "$COLOR_OVERLAY2"))
\$overlay1 = rgb($(theme_hex "$COLOR_OVERLAY1"))
\$overlay0 = rgb($(theme_hex "$COLOR_OVERLAY0"))
\$surface2 = rgb($(theme_hex "$COLOR_SURFACE2"))
\$surface1 = rgb($(theme_hex "$COLOR_SURFACE1"))
\$surface0 = rgb($(theme_hex "$COLOR_SURFACE0"))
\$base = rgb($(theme_hex "$COLOR_BASE"))
\$mantle = rgb($(theme_hex "$COLOR_MANTLE"))
\$crust = rgb($(theme_hex "$COLOR_CRUST"))

\$lock_text = \$text
\$lock_subtext = \$subtext1
\$lock_input_bg = rgba($crust_rgb, 0.45)
\$lock_input_fg = \$text
\$lock_input_border = rgba($surface2_rgb, 0.65)
\$lock_check = \$blue
\$lock_fail = \$red
\$lock_caps = \$yellow
\$lock_layout = rgba($text_rgb,0.95)
\$lock_shadow = rgba(0,0,0,0.75)
EOF_HYPR
}

