render_rmpc_palette() {
  local output="$1"

  cat >"$output" <<EOF_RON
#![enable(implicit_some)]
#![enable(unwrap_newtypes)]
#![enable(unwrap_variant_newtypes)]

// Generated by Hyprdots theme manager.
(
    background_color: "$COLOR_BASE",
    text_color: "$COLOR_TEXT",
    header_background_color: None,
    modal_background_color: "$COLOR_MANTLE",
    preview_label_style: ( fg: "$COLOR_MAUVE", ),
    preview_metadata_group_style: ( fg: "$COLOR_MAUVE", modifiers: "Bold", ),
    tab_bar: (
        enabled: true,
        active_style: ( fg: "$COLOR_BASE", bg: "$COLOR_BLUE", modifiers: "Bold", ),
        inactive_style: ( fg: "$COLOR_SUBTEXT0", ),
    ),
    highlighted_item_style: ( fg: "$COLOR_PINK", modifiers: "Bold", ),
    current_item_style: ( fg: "$COLOR_BASE", bg: "$COLOR_BLUE", modifiers: "Bold", ),
    borders_style: ( fg: "$COLOR_OVERLAY0", ),
    highlight_border_style: ( fg: "$COLOR_BLUE", ),
    progress_bar: (
        symbols: ["━", "━", "●"],
        track_style: ( fg: "$COLOR_SURFACE0", ),
        elapsed_style: ( fg: "$COLOR_BLUE", ),
        thumb_style: ( fg: "$COLOR_MAUVE", bg: "$COLOR_SURFACE0", ),
    ),
    scrollbar: (
        symbols: ["│", "█", "▲", "▼"],
        track_style: ( fg: "$COLOR_SURFACE0", ),
        ends_style: ( fg: "$COLOR_OVERLAY0", ),
        thumb_style: ( fg: "$COLOR_BLUE", ),
    ),
)
EOF_RON
}

render_yazi_flavor() {
  local output_dir="$1"

  mkdir -p -- "$output_dir"

  cat >"$output_dir/flavor.toml" <<EOF_TOML
#:schema https://yazi-rs.github.io/schemas/theme.json

# Generated by Hyprdots theme manager.

[app]
overall = { bg = "$COLOR_BASE" }

[mgr]
cwd = { fg = "$COLOR_BLUE" }

find_keyword = { fg = "$COLOR_YELLOW", bold = true, italic = true, underline = true }
find_position = { fg = "$COLOR_MAUVE", bg = "reset", bold = true, italic = true }

symlink_target = { fg = "$COLOR_TEAL", italic = true }

marker_copied = { fg = "$COLOR_GREEN", bg = "$COLOR_GREEN" }
marker_cut = { fg = "$COLOR_RED", bg = "$COLOR_RED" }
marker_marked = { fg = "$COLOR_TEAL", bg = "$COLOR_TEAL" }
marker_selected = { fg = "$COLOR_YELLOW", bg = "$COLOR_YELLOW" }

count_copied = { fg = "$COLOR_BASE", bg = "$COLOR_GREEN" }
count_cut = { fg = "$COLOR_BASE", bg = "$COLOR_RED" }
count_selected = { fg = "$COLOR_BASE", bg = "$COLOR_YELLOW" }

border_style = { fg = "$COLOR_SURFACE2" }

[tabs]
active = { fg = "$COLOR_BASE", bg = "$COLOR_BLUE", bold = true }
inactive = { fg = "$COLOR_SUBTEXT0", bg = "$COLOR_SURFACE0" }

sep_inner = { open = "", close = "" }
sep_outer = { open = "", close = "" }

[mode]
normal_main = { fg = "$COLOR_BASE", bg = "$COLOR_BLUE", bold = true }
normal_alt = { fg = "$COLOR_BLUE", bg = "$COLOR_SURFACE0" }

select_main = { fg = "$COLOR_BASE", bg = "$COLOR_MAUVE", bold = true }
select_alt = { fg = "$COLOR_MAUVE", bg = "$COLOR_SURFACE0" }

unset_main = { fg = "$COLOR_BASE", bg = "$COLOR_RED", bold = true }
unset_alt = { fg = "$COLOR_RED", bg = "$COLOR_SURFACE0" }

[indicator]
parent = { fg = "$COLOR_SUBTEXT0", bg = "$COLOR_SURFACE0" }
current = { fg = "$COLOR_BASE", bg = "$COLOR_BLUE", bold = true }
preview = { fg = "$COLOR_MAUVE", underline = true }

padding = { open = "", close = "" }

[status]
overall = { fg = "$COLOR_TEXT", bg = "$COLOR_BASE" }

sep_left = { open = "", close = "" }
sep_right = { open = "", close = "" }

perm_sep = { fg = "$COLOR_OVERLAY0" }
perm_type = { fg = "$COLOR_GREEN" }
perm_read = { fg = "$COLOR_YELLOW" }
perm_write = { fg = "$COLOR_RED" }
perm_exec = { fg = "$COLOR_TEAL" }

progress_label = { fg = "$COLOR_TEXT", bold = true }
progress_normal = { fg = "$COLOR_GREEN", bg = "$COLOR_SURFACE1" }
progress_error = { fg = "$COLOR_YELLOW", bg = "$COLOR_RED" }

[which]
border = { fg = "$COLOR_BLUE" }
mask = { bg = "$COLOR_MANTLE" }
cand = { fg = "$COLOR_TEAL" }
rest = { fg = "$COLOR_OVERLAY0" }
desc = { fg = "$COLOR_MAUVE" }
separator_style = { fg = "$COLOR_SURFACE2" }

[confirm]
border = { fg = "$COLOR_BLUE" }
title = { fg = "$COLOR_BLUE" }
body = { fg = "$COLOR_TEXT" }
list = { fg = "$COLOR_TEXT" }
btn_yes = { fg = "$COLOR_BASE", bg = "$COLOR_GREEN", bold = true }
btn_no = { fg = "$COLOR_BASE", bg = "$COLOR_RED", bold = true }

[spot]
border = { fg = "$COLOR_BLUE" }
title = { fg = "$COLOR_BLUE" }
tbl_col = { fg = "$COLOR_BLUE" }
tbl_cell = { fg = "$COLOR_YELLOW" }

[notify]
title_info = { fg = "$COLOR_GREEN" }
title_warn = { fg = "$COLOR_YELLOW" }
title_error = { fg = "$COLOR_RED" }

[pick]
border = { fg = "$COLOR_BLUE" }
active = { fg = "$COLOR_MAUVE", bold = true }
inactive = { fg = "$COLOR_TEXT" }

[input]
border = { fg = "$COLOR_BLUE" }
title = { fg = "$COLOR_TEXT" }
value = { fg = "$COLOR_TEXT" }
selected = { fg = "$COLOR_BASE", bg = "$COLOR_BLUE" }

[cmp]
border = { fg = "$COLOR_BLUE" }
active = { fg = "$COLOR_BASE", bg = "$COLOR_BLUE", bold = true }
inactive = { fg = "$COLOR_TEXT" }

[tasks]
border = { fg = "$COLOR_BLUE" }
title = { fg = "$COLOR_TEXT" }
hovered = { fg = "$COLOR_MAUVE", bold = true }

[help]
border = { fg = "$COLOR_BLUE" }
chord = { fg = "$COLOR_TEAL" }
action = { fg = "$COLOR_TEXT" }
hovered = { fg = "$COLOR_BASE", bg = "$COLOR_BLUE", bold = true }

[filetype]
rules = [
  { mime = "**/image/*", fg = "$COLOR_YELLOW" },
  { mime = "**/{audio,video}/*", fg = "$COLOR_MAUVE" },
  { mime = "**/application/{zip,rar,7z*,tar,gzip,xz,zstd,bzip*,lzma,compress,archive,cpio,arj,xar,ms-cab*}", fg = "$COLOR_RED" },
  { mime = "**/application/{pdf,doc,rtf}", fg = "$COLOR_TEAL" },

  { url = "*", is = "orphan", bg = "$COLOR_RED" },
  { url = "*", is = "exec", fg = "$COLOR_GREEN" },

  { url = "*/", fg = "$COLOR_BLUE" },
]
EOF_TOML

  cat >"$output_dir/tmtheme.xml" <<EOF_XML
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>name</key>
  <string>Hyprdots Current</string>

  <key>settings</key>
  <array>
    <dict>
      <key>settings</key>
      <dict>
        <key>background</key>
        <string>$COLOR_BASE</string>
        <key>foreground</key>
        <string>$COLOR_TEXT</string>
        <key>caret</key>
        <string>$COLOR_ROSEWATER</string>
        <key>selection</key>
        <string>$COLOR_SURFACE2</string>
      </dict>
    </dict>

    <dict>
      <key>name</key>
      <string>Comment</string>
      <key>scope</key>
      <string>comment</string>
      <key>settings</key>
      <dict>
        <key>foreground</key>
        <string>$COLOR_OVERLAY0</string>
        <key>fontStyle</key>
        <string>italic</string>
      </dict>
    </dict>

    <dict>
      <key>name</key>
      <string>String</string>
      <key>scope</key>
      <string>string</string>
      <key>settings</key>
      <dict>
        <key>foreground</key>
        <string>$COLOR_GREEN</string>
      </dict>
    </dict>

    <dict>
      <key>name</key>
      <string>Keyword</string>
      <key>scope</key>
      <string>keyword, storage</string>
      <key>settings</key>
      <dict>
        <key>foreground</key>
        <string>$COLOR_MAUVE</string>
      </dict>
    </dict>

    <dict>
      <key>name</key>
      <string>Number</string>
      <key>scope</key>
      <string>constant.numeric, constant.language</string>
      <key>settings</key>
      <dict>
        <key>foreground</key>
        <string>$COLOR_PEACH</string>
      </dict>
    </dict>

    <dict>
      <key>name</key>
      <string>Function</string>
      <key>scope</key>
      <string>entity.name.function</string>
      <key>settings</key>
      <dict>
        <key>foreground</key>
        <string>$COLOR_BLUE</string>
      </dict>
    </dict>

    <dict>
      <key>name</key>
      <string>Type</string>
      <key>scope</key>
      <string>entity.name.type, support.type</string>
      <key>settings</key>
      <dict>
        <key>foreground</key>
        <string>$COLOR_YELLOW</string>
      </dict>
    </dict>
  </array>
</dict>
</plist>
EOF_XML
}

render_tmux_palette() {
  local output="$1"

  cat >"$output" <<EOF_TMUX
# Generated by Hyprdots theme manager.

# Base
set -g @thm_bg "$COLOR_BASE"
set -g @thm_fg "$COLOR_TEXT"

# Colors
set -g @thm_rosewater "$COLOR_ROSEWATER"
set -g @thm_flamingo "$COLOR_FLAMINGO"
set -g @thm_pink "$COLOR_PINK"
set -g @thm_mauve "$COLOR_MAUVE"
set -g @thm_red "$COLOR_RED"
set -g @thm_maroon "$COLOR_MAROON"
set -g @thm_peach "$COLOR_PEACH"
set -g @thm_yellow "$COLOR_YELLOW"
set -g @thm_green "$COLOR_GREEN"
set -g @thm_teal "$COLOR_TEAL"
set -g @thm_sky "$COLOR_SKY"
set -g @thm_sapphire "$COLOR_SAPPHIRE"
set -g @thm_blue "$COLOR_BLUE"
set -g @thm_lavender "$COLOR_LAVENDER"

# Text
set -g @thm_subtext_1 "$COLOR_SUBTEXT1"
set -g @thm_subtext_0 "$COLOR_SUBTEXT0"

# Overlays
set -g @thm_overlay_2 "$COLOR_OVERLAY2"
set -g @thm_overlay_1 "$COLOR_OVERLAY1"
set -g @thm_overlay_0 "$COLOR_OVERLAY0"

# Surfaces
set -g @thm_surface_2 "$COLOR_SURFACE2"
set -g @thm_surface_1 "$COLOR_SURFACE1"
set -g @thm_surface_0 "$COLOR_SURFACE0"
set -g @thm_mantle "$COLOR_MANTLE"
set -g @thm_crust "$COLOR_CRUST"

# Native tmux UI
set -g status-style "bg=$COLOR_BASE,fg=$COLOR_TEXT"
set -g message-style "bg=$COLOR_SURFACE0,fg=$COLOR_TEXT"
set -g message-command-style "bg=$COLOR_SURFACE0,fg=$COLOR_TEXT"

set -g mode-style "bg=$COLOR_BLUE,fg=$COLOR_CRUST"

set -g pane-border-style "fg=$COLOR_SURFACE1"
set -g pane-active-border-style "fg=$COLOR_BLUE"

set -g @catppuccin_status_background "$COLOR_BASE"
EOF_TMUX
}

