themes {
    current {
        bg "$COLOR_SURFACE2"
        fg "$COLOR_TEXT"
        red "$COLOR_RED"
        green "$COLOR_GREEN"
        blue "$COLOR_BLUE"
        yellow "$COLOR_YELLOW"
        magenta "$COLOR_PINK"
        orange "$COLOR_PEACH"
        cyan "$COLOR_SKY"
        black "$COLOR_MANTLE"
        white "$COLOR_TEXT"
