render_palette_env() {
  local output="$1"
  local variable_name

  {
    printf '# Generated by Hyprdots theme manager.\n'
    printf 'THEME_NAME=%q\n' "$THEME_NAME"
    printf 'THEME_DISPLAY_NAME=%q\n' "$THEME_DISPLAY_NAME"

    for variable_name in "${THEME_COLOR_VARIABLES[@]}"; do
      printf '%s=%q\n' "$variable_name" "${!variable_name}"
    done
  } >"$output"
}

render_theme_directory() {
  local output_dir="$1"

  mkdir -p -- "$output_dir"

  render_palette_env "$output_dir/palette.env"
  render_rasi_palette "$output_dir/rofi.rasi"
  cp -- "$output_dir/rofi.rasi" "$output_dir/networkmanager.rasi"
  cp -- "$output_dir/rofi.rasi" "$output_dir/bluetooth.rasi"
  render_waybar_palette "$output_dir/waybar.css"
  render_swaync_palette "$output_dir/swaync.css"
  render_wlogout_palette "$output_dir/wlogout.css"
  render_hyprlock_palette "$output_dir/hyprlock.conf"
  render_hyprland_palette "$output_dir/hyprland.lua"
  render_ghostty_palette "$output_dir/ghostty.conf"
  render_starship_palette "$output_dir/starship.toml"
  render_btop_palette "$output_dir/btop.theme"
  render_rmpc_palette "$output_dir/rmpc.ron"
  render_tmux_palette "$output_dir/tmux.conf"
  render_zellij_palette "$output_dir/zellij.kdl"
  render_yazi_flavor "$output_dir/yazi.yazi"
  render_nvim_palette "$output_dir/nvim.lua"
}

render_theme() {
  local theme_name="$1"
  local temporary_dir
  local destination
  local temporary_link

  theme_prepare_runtime
  theme_load "$theme_name"

  temporary_dir="$(mktemp -d "$THEME_CACHE_ROOT/.render.XXXXXX")"
  destination="$THEME_RENDER_ROOT/$theme_name"
  temporary_link="$THEME_CACHE_ROOT/.current.$$"

  # Invoked indirectly by the RETURN trap below.
  # shellcheck disable=SC2329
  cleanup_theme_render() {
    rm -rf -- "${temporary_dir:-}"
    rm -f -- "${temporary_link:-}"
  }

  trap cleanup_theme_render RETURN

  render_theme_directory "$temporary_dir"

  rm -rf -- "$destination"
  mv -- "$temporary_dir" "$destination"
  temporary_dir=""

  ln -s -- "rendered/$theme_name" "$temporary_link"
  mv -Tf -- "$temporary_link" "$THEME_ACTIVE_LINK"
  temporary_link=""

  trap - RETURN
}
